import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def find_blocks(g):
    H,W=len(g),len(g[0]); blocks=[]
    for r in range(H-2):
        for c in range(W-2):
            v=g[r][c]
            if v and all(g[r+i][c+j]==v for i in range(3) for j in range(3)):
                blocks.append((v,r,c))
    return blocks

def transform(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    beams={'h':{},'v':{}}
    for v,r,c in find_blocks(g):
        beams['h'].setdefault(r+v*0,[]).append((r+1,v)) if False else None
        beams.setdefault('hrows',{})[r+1]=v
        beams.setdefault('vcols',{})[c+1]=v
    hr,vc=beams.get('hrows',{}),beams.get('vcols',{})
    # horizontal beams
    for r,v in hr.items():
        for c in range(W): out[r][c]=v
    for c,v in vc.items():
        for r in range(H): out[r][c]=v
    # intersections of different colors -> 0
    for r,vr in hr.items():
        for c,cv in vc.items():
            if vr!=cv: out[r][c]=0
    return out

o=transform(G['Demo pair 1 input'])
print(o==G['Demo pair 1 output'])
res=transform(G['Test input'])
for row in res: print(' '.join(map(str,row)))
print(json.dumps(res))

